 return sum(H[i][j]*sum(X[i][k]*X[j][k] for k in range(3)) for i in range(2) for j in range(2))
def new(X):
 return sum(X[i][k]*H[i][j]*X[j][k] for i in range(2) for j in range(2) for k in range(3))
print({'old_num':old(E),'new_num':new(E),'old_den':old(W),'new_den':new(W),'ratio':new(E)/max(new(W),1e-8)})
